overlapping-subproblems.pseudocode:
def fib_naive(n):  # 중복 호출로 O(2^n)
    if n <= 1:
        return n
    return fib_naive(n - 1) + fib_naive(n - 2)

def fib_memo(n, memo):  # 하향식 메모이제이션 O(n)
    if n <= 1:
        return n
    if n not in memo:  # 부분 문제는 1회만 계산
        a = fib_memo(n - 1, memo)
        memo[n] = a + fib_memo(n - 2, memo)
    return memo[n]

def fib_tab(n):  # 상향식 타뷸레이션 O(n)
    dp = [0, 1] + [0] * max(0, n - 1)
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]
